#pragma once
// Unicode character names (round 77): what a string literal's \N{...}
// escape names, as in CPython - include/NyUniNamesData.hpp (generated by
// tools/gen_unicode_names.py from Python's own unicodedata) plus the names
// Unicode derives from the code point (CJK UNIFIED IDEOGRAPH-4E00, HANGUL
// SYLLABLE GA, ...). Names match as unicodedata.lookup's do: without
// regard to case, except the HANGUL SYLLABLE and CJK UNIFIED IDEOGRAPH ones;
// name aliases too (round 84), named sequences for unicodedata.lookup only.
#include <cstdint>
#include <string>
#include <vector>

namespace nyuni {

// The code point called `name` (an alias too); false when no character has
// that name - what a \N{...} escape names.
bool lookup(const std::string& name, uint32_t& cp);

// unicodedata.lookup (round 84): the character or named sequence called
// `name`; ucd_3_2_0 looks in Unicode 3.2.0 (no aliases, no sequences).
bool lookup_seq(const std::string& name, std::vector<uint32_t>& out, bool ucd_3_2_0 = false);

// unicodedata.ucd_3_2_0.name: "" for a character Unicode 3.2.0 lacks.
std::string name_3_2_0(uint32_t cp);

// The name of code point cp, "" when it has none (unicodedata.name).
std::string name(uint32_t cp);

}  // namespace nyuni
